import { DEFAULT_SITE } from './defaults.js';
const DEMO=Boolean(window.TM_DEMO);
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const $money=n=>'$'+Number(n||0).toLocaleString('en-CA',{maximumFractionDigits:0});
const dateFmt=iso=>{try{return new Date(iso+'T12:00:00').toLocaleDateString('en-CA',{month:'short',day:'numeric',year:'numeric'});}catch{return iso}};
const tFmt=t=>{const [h,m]=String(t||'09:00').split(':').map(Number);return (h%12||12)+':'+String(m).padStart(2,'0')+' '+(h<12?'AM':'PM');};
const clone=x=>JSON.parse(JSON.stringify(x));
const localDay=n=>{const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const p=Object.fromEntries(parts.filter(x=>x.type!=='literal').map(x=>[x.type,x.value]));const d=new Date(`${p.year}-${p.month}-${p.day}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);};
const state={logged:false,view:'overview',site:clone(DEFAULT_SITE),draft:clone(DEFAULT_SITE),bookings:[],requests:[],accounts:[],selected:null,filters:{text:'',status:'all',source:'all'},calendarStart:0,assistantDraft:null};
const sampleId=n=>'00000000-0000-4000-8000-'+String(n).padStart(12,'0');
const demoDB={site:clone(DEFAULT_SITE),bookings:[{id:sampleId(1),reference:'TM-DEMO0001',customer_name:'Jordan Miller',email:'jordan@example.com',phone:'647-555-0101',vehicle:'suv',service_location:'dropoff',address:'',appointment_date:localDay(0),appointment_time:'11:00',status:'confirmed',quoted_price:100,notes:'Needs extra attention on floor mats',business_account_id:null},{id:sampleId(2),reference:'TM-DEMO0002',customer_name:'Alex Rivera',email:'alex@example.com',phone:'416-555-0102',vehicle:'sedan',service_location:'mobile',address:'Demo address (not real)',appointment_date:localDay(1),appointment_time:'09:00',status:'pending',quoted_price:80,notes:'Water and outlet available',business_account_id:null},{id:sampleId(3),reference:'TM-DEMO0003',customer_name:'Morgan Lee',email:'morgan@example.com',phone:'647-555-0103',vehicle:'van',service_location:'dropoff',address:'',appointment_date:localDay(2),appointment_time:'13:00',status:'confirmed',quoted_price:75,notes:'Company fleet vehicle',business_account_id:sampleId(8),business_label:'Northline Fleet',fleet_make:'Ford',fleet_model:'Transit',fleet_label:'VAN-04',department_name:'Operations'},{id:sampleId(4),reference:'TM-DEMO0004',customer_name:'Casey Brooks',email:'casey@example.com',phone:'416-555-0104',vehicle:'truck',service_location:'dropoff',address:'',appointment_date:localDay(4),appointment_time:'15:00',status:'pending',quoted_price:120,notes:'Pickup truck',business_account_id:null}],requests:[{id:sampleId(6),booking_id:sampleId(2),reference:'TM-DEMO0002',customer_name:'Alex Rivera',kind:'reschedule',message:'Could we move the appointment to the afternoon?',status:'open',appointment_date:localDay(1),appointment_time:'09:00',created_at:new Date().toISOString()},{id:sampleId(7),booking_id:sampleId(3),reference:'TM-DEMO0003',customer_name:'Morgan Lee',kind:'cancel',message:'Please confirm whether this can be cancelled.',status:'open',appointment_date:localDay(2),appointment_time:'13:00',created_at:new Date().toISOString()}],accounts:[{id:sampleId(8),label:'Northline Fleet',active:1,prices:{sedan:60,suv:65,truck:75,van:75,sprinter:100},created_at:new Date().toISOString()}]};
async function request(path,opts={}){
 if(DEMO)return mock(path,opts);
 const r=await fetch('/api/'+path,{credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(15000),...opts,headers:{...(opts.body instanceof FormData?{}:opts.body?{'Content-Type':'application/json'}:{}),...(opts.headers||{})}});let d;try{d=await r.json()}catch{throw Error('Server returned an invalid response')}if(!r.ok||d.ok===false)throw Error(d.error||'Request failed');return d;
}
async function mock(path,opts){await new Promise(r=>setTimeout(r,100));const method=opts.method||'GET',body=opts.body instanceof FormData?null:opts.body?JSON.parse(opts.body):{};if(path==='login')return {ok:true,role:'admin'};if(path==='logout')return {ok:true};if(path==='admin/site'){if(method==='PUT'){demoDB.site=clone(body.site);return {ok:true,site:clone(demoDB.site)}}return {ok:true,site:clone(demoDB.site)}}if(path==='admin/bookings')return {ok:true,bookings:clone(demoDB.bookings)};if(path==='admin/requests')return {ok:true,requests:clone(demoDB.requests)};if(path==='admin/business'){if(method==='POST'){const a={id:sampleId(50+demoDB.accounts.length),label:body.label,prices:body.prices,active:1};demoDB.accounts.push(a);return {ok:true,id:a.id,code:body.code||'TM-DEMO-CODE'}}return {ok:true,accounts:clone(demoDB.accounts)}}if(path.startsWith('admin/business/')){const id=path.split('/')[2],a=demoDB.accounts.find(x=>x.id===id);if(path.endsWith('/fleet'))return {ok:true,departments:[{id:'d1',name:'Operations'}],fleet:[{id:'f1',make:'Ford',model:'Transit',model_year:'2024',label:'VAN-04',department:'Operations'}]};if(path.endsWith('/rotate'))return {ok:true,code:'TM-DEMO-NEWCODE'};if(method==='PUT'){Object.assign(a,body);return {ok:true}}}if(path.startsWith('admin/bookings/')&&method==='PUT'){const b=demoDB.bookings.find(x=>x.id===path.split('/')[2]);if(!b)throw Error('Booking missing');Object.assign(b,{customer_name:body.name,email:body.email,phone:body.phone,vehicle:body.vehicle,appointment_date:body.date,appointment_time:body.time,service_location:body.location,address:body.address,quoted_price:body.price,status:body.status,notes:body.notes});return {ok:true}}if(path.startsWith('admin/bookings/')&&method==='DELETE'){const i=demoDB.bookings.findIndex(x=>x.id===path.split('/')[2]&&x.reference===body.reference);if(i<0)throw Error('Reference incorrect');demoDB.bookings.splice(i,1);return {ok:true}}if(path.startsWith('admin/requests/')&&method==='PUT'){let a=demoDB.requests.find(x=>x.id===path.split('/')[2]);a.status=body.status;return {ok:true}}if(path==='admin/media'&&method==='POST'){return {ok:true,url:'https://images.unsplash.com/photo-1552519507-da3b142c6e3d?w=1200'}}throw Error('Demo endpoint not configured: '+path)}
function toast(message,error=false){const el=$('#tm-toast');el.textContent=message;el.classList.toggle('error',error);el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,4800)}
const statusTag=s=>`<span class="tm-tag ${esc(s)}">${esc((s||'unknown').replace(/^./,a=>a.toUpperCase()))}</span>`;
function heading(label,title,description,actions=''){return `<div class="tm-heading"><div><span class="tm-overline">${label}</span><h1>${title}</h1><p>${description}</p></div><div class="tm-h-actions">${actions}</div></div>`}
async function signin(e){e.preventDefault();const btn=$('#tm-login-btn');btn.disabled=true;$('#tm-login-error').hidden=true;try{if(!DEMO){await request('logout',{method:'POST',body:JSON.stringify({})});}await request('login',{method:'POST',body:JSON.stringify({kind:'admin',password:$('#tm-pass').value})});$('#tm-pass').value='';state.logged=true;$('#tm-gate').hidden=true;$('#tm-workspace').hidden=false;await refresh();navigate('overview')}catch(err){const el=$('#tm-login-error');el.textContent=err.message;el.hidden=false}finally{btn.disabled=false}}
async function signout(){try{await request('logout',{method:'POST',body:JSON.stringify({})})}catch{}state.logged=false;state.bookings=[];state.requests=[];state.accounts=[];$('#tm-workspace').hidden=true;$('#tm-gate').hidden=false;closeDrawer();navigate('overview',false);$('#tm-pass').value='';$('#tm-pass').focus()}
async function refresh(){if(!state.logged)return;try{const data=await Promise.all([request('admin/site'),request('admin/bookings'),request('admin/requests'),request('admin/business')]);state.site=data[0].site;state.draft=clone(state.site);state.bookings=data[1].bookings||[];state.requests=data[2].requests||[];state.accounts=data[3].accounts||[];$('#tm-pending-count').textContent=state.bookings.filter(x=>x.status==='pending').length;$('#tm-request-count').textContent=state.requests.filter(x=>x.status==='open').length}catch(err){toast('Could not load studio data: '+err.message,true)}}
function navigate(view,render=true){state.view=view;$$('.tm-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#tm-breadcrumb').textContent='WORKSPACE / '+view.replace(/\b\w/g,c=>c.toUpperCase());$('#tm-sidebar').classList.remove('open');if(render)draw();}
function draw(){const root=$('#tm-view-root');const fn=({overview:overviewView,calendar:calendarView,bookings:bookingsView,requests:requestsView,customers:customersView,business:businessView,website:websiteView,gallery:galleryView,pricing:pricingView,assistant:assistantView,settings:settingsView})[state.view]||overviewView;root.innerHTML=fn();bindView();}
function overviewView(){const pending=state.bookings.filter(x=>x.status==='pending').length, req=state.requests.filter(x=>x.status==='open').length,confirmed=state.bookings.filter(x=>x.status==='confirmed').length,today=state.bookings.filter(x=>x.appointment_date===localDay(0)&&!['cancelled','completed'].includes(x.status));return heading('WELCOME BACK / OPERATIONS','Your day, under control.','The next appointment, the next request and your most-used tools — all in one place.',`<button class="tm-outline" data-go="website">Edit website ↗</button><button class="tm-primary" data-go="bookings">Manage bookings →</button>`)+`<div class="tm-grid-4"><div class="tm-tile"><span class="tm-t-label">TODAY'S JOBS</span><strong>${today.length}</strong><small>Scheduled for today</small></div><div class="tm-tile"><span class="tm-t-label">NEEDS REVIEW</span><strong>${req}</strong><small>Customer change requests</small></div><div class="tm-tile"><span class="tm-t-label">AWAITING CONFIRMATION</span><strong>${pending}</strong><small>Booking requests</small></div><div class="tm-tile"><span class="tm-t-label">CONFIRMED BOOKINGS</span><strong>${confirmed}</strong><small>Upcoming appointments</small></div></div><div class="tm-two-col"><section class="tm-panel"><div class="tm-panel-head"><div><h2>Coming up</h2><p>Your next appointments</p></div><button class="tm-link" data-go="calendar">Full calendar ↗</button></div><div class="tm-panel-body">${state.bookings.filter(x=>['pending','confirmed','in_progress'].includes(x.status)).sort((a,b)=>(a.appointment_date+a.appointment_time).localeCompare(b.appointment_date+b.appointment_time)).slice(0,5).map(b=>`<div class="tm-appointment"><div class="tm-appointment-time">${tFmt(b.appointment_time)}</div><div><strong>${esc(b.customer_name)}</strong><p>${dateFmt(b.appointment_date)} · ${esc(vehicleName(b.vehicle))}${b.business_label?' · '+esc(b.business_label):''}</p></div><button class="tm-link" data-booking-id="${esc(b.id)}">Open ↗</button></div>`).join('')||'<div class="tm-empty">No upcoming appointments.</div>'}</div></section><section class="tm-panel"><div class="tm-panel-head"><div><h2>Your attention</h2><p>Take action without hunting through menus</p></div><button class="tm-link" data-go="requests">View all ↗</button></div><div class="tm-panel-body tm-attention">${state.requests.filter(x=>x.status==='open').slice(0,4).map(r=>`<div class="tm-attention-card"><span class="tm-dot"></span><div><strong>${esc(r.kind==='cancel'?'Cancellation':'Reschedule')} · ${esc(r.reference)}</strong><p>${esc(r.customer_name)} has requested a change.</p></div><button data-go="requests">Review ↗</button></div>`).join('')||'<div class="tm-empty">All caught up. No customer requests waiting.</div>'}${pending?`<div class="tm-attention-card"><span class="tm-dot"></span><div><strong>${pending} booking${pending===1?'':'s'} awaiting confirmation</strong><p>Review appointment details before confirming.</p></div><button data-go="bookings">Open ↗</button></div>`:''}</div></section></div><div class="tm-two-col"><section class="tm-panel"><div class="tm-panel-head"><h2>Quick actions</h2></div><div class="tm-panel-body tm-actions"><button class="tm-outline" data-go="calendar">▦ Calendar</button><button class="tm-outline" data-go="business">▥ Client accounts</button><button class="tm-outline" data-go="gallery">▧ Upload photos</button><button class="tm-outline" data-go="pricing">＄ Change pricing</button></div></section><section class="tm-panel"><div class="tm-panel-head"><h2>Your website</h2><a class="tm-link" href="/" target="_blank" rel="noopener">View live ↗</a></div><div class="tm-panel-body"><p class="tm-muted">Published theme: <strong>${esc((state.site.theme||'default').toUpperCase())}</strong></p><button class="tm-outline" data-go="website">Open website editor ↗</button></div></section></div>`}
const vehicleName=id=>state.site.vehicles?.find(x=>x.id===id)?.name||id;
function bookingsView(){return heading('APPOINTMENTS / FULL CONTROL','Every booking, one place.','Search, inspect, update, confirm and remove bookings. Business bookings appear alongside public bookings.',`<button class="tm-outline" data-go="calendar">Schedule view ↗</button><button class="tm-primary" data-go="requests">Customer requests →</button>`)+`<div class="tm-toolbar"><input id="tm-book-search" placeholder="Search name, company, reference, vehicle..." value="${esc(state.filters.text)}" aria-label="Search bookings"><select id="tm-book-status" aria-label="Filter status">${['all','pending','confirmed','in_progress','completed','cancelled'].map(x=>`<option value="${x}" ${state.filters.status===x?'selected':''}>${x==='all'?'All statuses':x[0].toUpperCase()+x.slice(1)}</option>`).join('')}</select><select id="tm-book-source" aria-label="Filter account type"><option value="all">All customers</option><option value="public" ${state.filters.source==='public'?'selected':''}>Public</option><option value="business" ${state.filters.source==='business'?'selected':''}>Business</option></select></div><div class="tm-panel tm-table-scroll"><table class="tm-table"><thead><tr><th>Customer / reference</th><th>Vehicle</th><th>Appointment</th><th>Account</th><th>Status</th><th>Price</th><th></th></tr></thead><tbody id="tm-book-body"></tbody></table></div>`}
function drawBookingRows(){const tbody=$('#tm-book-body');if(!tbody)return;const q=state.filters.text.toLowerCase().trim();const list=state.bookings.filter(b=>(state.filters.status==='all'||b.status===state.filters.status)&&(state.filters.source==='all'||(state.filters.source==='business'?Boolean(b.business_account_id):!b.business_account_id))&&(!q||[b.customer_name,b.reference,b.business_label,b.fleet_make,b.fleet_model,b.vehicle].some(v=>String(v||'').toLowerCase().includes(q))));tbody.innerHTML=list.map(b=>`<tr><td><strong>${esc(b.customer_name)}</strong><span class="tm-sub">${esc(b.reference)}</span></td><td>${esc(b.fleet_make?b.fleet_make+' '+b.fleet_model:vehicleName(b.vehicle))}<span class="tm-sub">${esc(vehicleName(b.vehicle))}</span></td><td>${dateFmt(b.appointment_date)}<span class="tm-sub">${tFmt(b.appointment_time)}</span></td><td>${b.business_account_id?`<span class="tm-tag">${esc(b.business_label||'Business')}</span>`:'Public'}</td><td>${statusTag(b.status)}</td><td>${$money(b.quoted_price)}</td><td><button data-booking-id="${esc(b.id)}">Open ↗</button></td></tr>`).join('')||'<tr><td colspan="7" class="tm-empty">No matching bookings.</td></tr>'}
function calendarView(){const selected=localDay(state.calendarStart);const all=Array.from({length:14},(_,i)=>{const d=localDay(i+state.calendarStart),items=state.bookings.filter(x=>x.appointment_date===d&&!['cancelled'].includes(x.status));return {date:d,items}});return heading('SCHEDULE / YOUR TIME','The calendar.','See appointments in context. Select a day for its bookings and open any record to reschedule or update it.',`<button class="tm-outline" id="tm-calendar-prev">← Previous</button><button class="tm-outline" id="tm-calendar-next">Next →</button>`)+`<div class="tm-panel"><div class="tm-panel-head"><h2>${dateFmt(selected)} — ${dateFmt(localDay(state.calendarStart+13))}</h2><span class="tm-muted">Two-week schedule</span></div><div class="tm-panel-body"><div class="tm-date-grid">${all.map(x=>`<button class="tm-date ${x.date===localDay(0)?'today':''} ${x.items.length>=state.site.booking.maxPerDay?'full':''}" data-calendar-day="${x.date}"><small>${new Date(x.date+'T12:00:00Z').toLocaleDateString('en-CA',{weekday:'short'})}</small><strong>${new Date(x.date+'T12:00:00Z').getUTCDate()}</strong><span>${x.items.length} booking${x.items.length===1?'':'s'} ${x.items.length>=state.site.booking.maxPerDay?'· FULL':''}</span></button>`).join('')}</div></div></div><div id="tm-day-detail" class="tm-panel" style="margin-top:16px"><div class="tm-panel-body tm-muted">Select a date to see scheduled vehicles.</div></div>`}
function requestsView(){const open=state.requests.filter(x=>x.status==='open'),closed=state.requests.filter(x=>x.status!=='open');return heading('CUSTOMER REQUESTS / REVIEW','Nothing gets buried.','Every change or cancellation request has its own place. Approving a request does not silently change the appointment.',`<button class="tm-outline" data-go="bookings">Open bookings ↗</button>`)+`<div class="tm-tabs"><button class="active" id="tm-show-open">Open (${open.length})</button><button id="tm-show-reviewed">Reviewed (${closed.length})</button></div><div class="tm-rows" id="tm-requests-list">${requestList(open)}</div>`}
function requestList(items){return items.length?items.map(r=>`<article class="tm-row-card"><div><span class="tm-overline">${esc(r.kind==='cancel'?'CANCELLATION REQUEST':'APPOINTMENT CHANGE')}</span><h3 style="margin:7px 0">${esc(r.customer_name)} · ${esc(r.reference)}</h3><p>${esc(r.message||'No message supplied')} · ${dateFmt(r.appointment_date)} ${tFmt(r.appointment_time)}</p>${statusTag(r.status)}</div><div class="tm-actions">${r.status==='open'?`<button class="tm-outline" data-request="${esc(r.id)}" data-review="approved">Mark reviewed</button><button class="tm-outline" data-request="${esc(r.id)}" data-review="declined">Decline</button>`:''}<button class="tm-primary" data-booking-id="${esc(r.booking_id)}">Edit appointment ↗</button></div></article>`).join(''):'<div class="tm-panel"><div class="tm-empty">No requests in this category.</div></div>'}
function customersView(){const customers=new Map();for(const b of state.bookings){const id=b.email.toLowerCase();if(!customers.has(id))customers.set(id,{name:b.customer_name,email:b.email,phone:b.phone,bookings:[]});customers.get(id).bookings.push(b)}return heading('CLIENT HISTORY / RELATIONSHIPS','Your customers.','Search existing customers and open any of their bookings. No separate customer database required for this view.')+`<div class="tm-panel tm-table-scroll"><table class="tm-table"><thead><tr><th>Name</th><th>Contact</th><th>Bookings</th><th>Latest appointment</th><th></th></tr></thead><tbody>${[...customers.values()].map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${esc(c.email)}<span class="tm-sub">${esc(c.phone)}</span></td><td>${c.bookings.length}</td><td>${dateFmt(c.bookings.map(x=>x.appointment_date).sort().at(-1))}</td><td><button data-booking-id="${esc(c.bookings.at(-1).id)}">Open latest ↗</button></td></tr>`).join('')||'<tr><td class="tm-empty">No customers yet.</td></tr>'}</tbody></table></div><div class="tm-split-note">This customer list is derived from bookings. Customer notes, consent settings, and a standalone CRM can be added later without inventing records.</div>`}
function businessView(){return heading('COMMERCIAL CLIENTS / FLEET','Business accounts.','Control private rates, access codes, and company vehicle lists — without mixing them into your public website.',`<button class="tm-primary" id="tm-new-business">+ Add business account</button>`)+`<div class="tm-rows">${state.accounts.map(a=>`<article class="tm-row-card"><div><h3 style="margin:0 0 7px">${esc(a.label)}</h3><p>Account ${a.active?'active':'disabled'} · ${Object.keys(a.prices||{}).length} vehicle rate categories</p><span class="tm-tag ${a.active?'confirmed':'cancelled'}">${a.active?'ACTIVE':'DISABLED'}</span></div><div class="tm-actions"><button class="tm-outline" data-company-fleet="${esc(a.id)}">Departments & fleet</button><button class="tm-outline" data-company-edit="${esc(a.id)}">Edit rates</button><button class="tm-outline" data-company-rotate="${esc(a.id)}">New access code</button></div></article>`).join('')||'<div class="tm-panel"><div class="tm-empty">No business accounts yet. Use Add business account above.</div></div>'}</div>`}
function websiteView(){const d=state.draft;return heading('WEBSITE STUDIO / PUBLISHING','Make it yours.','Control homepage content and the full seasonal edition. Preview changes before saving the public website.',`<button class="tm-outline" id="tm-reset-draft">Discard draft</button><button class="tm-primary" id="tm-save-site">Save website changes ↗</button>`)+`<div class="tm-two-col"><div><div class="tm-form-card"><h3>Homepage content</h3><div class="tm-field"><label for="tm-hero-title">Main headline</label><input id="tm-hero-title" data-sitepath="hero.title" value="${esc(d.hero.title)}"></div><div class="tm-field"><label for="tm-hero-desc">Homepage description</label><textarea id="tm-hero-desc" data-sitepath="hero.description">${esc(d.hero.description)}</textarea></div><div class="tm-field"><label for="tm-hero-image">Hero image URL</label><input id="tm-hero-image" data-sitepath="hero.image" value="${esc(d.hero.image)}" placeholder="https://..."></div><div class="tm-field"><label for="tm-about">About TM Detailers</label><textarea id="tm-about" data-sitepath="about.body">${esc(d.about.body)}</textarea></div><div class="tm-field"><label><input type="checkbox" data-sitecheck="announcement.enabled" ${d.announcement.enabled?'checked':''}> Show announcement banner</label><input data-sitepath="announcement.text" value="${esc(d.announcement.text)}"></div></div><div class="tm-form-card" style="margin-top:14px"><h3>Holiday editions</h3><p class="tm-muted">Change the actual greeting, hero, seasonal colours and seasonal rates together. These settings drive the customer-facing theme.</p><div class="tm-theme-grid">${themeButtons(d.theme)}</div><div class="tm-divider"></div><div class="tm-settings-grid"><div class="tm-field"><label>Seasonal greeting</label><input data-themeprop="greeting" value="${esc(d.themeProfiles[d.theme]?.greeting||'')}"></div><div class="tm-field"><label>Holiday headline</label><input data-themeprop="headline" value="${esc(d.themeProfiles[d.theme]?.headline||'')}"></div><div class="tm-field tm-field-full"><label>Seasonal message</label><textarea data-themeprop="description">${esc(d.themeProfiles[d.theme]?.description||'')}</textarea></div><div class="tm-field"><label>Accent colour</label><input type="color" data-themeprop="accent" value="${esc(d.themeProfiles[d.theme]?.accent||'#b49b78')}"></div><div class="tm-field"><label>Background colour</label><input type="color" data-themeprop="background" value="${esc(d.themeProfiles[d.theme]?.background||'#121614')}"></div></div><div class="tm-field"><label>Holiday hero image URL</label><input data-themeprop="heroImage" value="${esc(d.themeProfiles[d.theme]?.heroImage||'')}"></div><div class="tm-settings-grid">${d.vehicles.map(v=>`<div class="tm-field"><label>${esc(v.name)} — holiday price</label><input type="number" min="0" max="10000" data-season-price="${esc(v.id)}" placeholder="Use regular price ($${esc(v.price)})" value="${esc(d.themeProfiles[d.theme]?.prices?.[v.id]??'')}"></div>`).join('')}</div></div></div><div><section class="tm-panel"><div class="tm-panel-head"><h2>Preview before you publish</h2></div><div class="tm-panel-body"><div class="tm-site-preview"><div class="tm-preview-hero" id="tm-web-preview" style="background:${esc(d.themeProfiles[d.theme]?.background||'#1d2320')}"><span class="tm-overline" id="tm-web-greeting">${esc(d.themeProfiles[d.theme]?.greeting||'TM DETAILERS')}</span><h2 id="tm-web-title">${esc(d.themeProfiles[d.theme]?.headline||d.hero.title)}</h2><p id="tm-web-description">${esc(d.themeProfiles[d.theme]?.description||d.hero.description)}</p></div></div><p class="tm-muted" style="font-size:11px;line-height:1.7">This preview shows text and colours. Real hero images are rendered on the public site.</p><a href="/" target="_blank" rel="noopener" class="tm-link">Open public site ↗</a></div></section><div class="tm-split-note">Website changes do not take effect until you press Save. Owner controls and customer data are not exposed through your homepage.</div></div></div>`}
const themeCatalog=[['default','Everyday','#171c1b','#d0c1a2'],['eid','Eid','#113529','#d3b776'],['christmas','Christmas','#1b3932','#d6b78f'],['thanksgiving','Thanksgiving','#4d2c20','#e9a261'],['halloween','Halloween','#291d39','#ed924e'],['newyear','New Year','#1a2441','#e1d9b4']];
function themeButtons(current){return themeCatalog.map(([id,label,bg,fg])=>`<button data-theme="${id}" class="tm-theme-option ${current===id?'active':''}" style="background:${bg};color:${fg}"><strong>${label}</strong><small>${id==='default'?'Standard TM identity':'Seasonal edition'}</small></button>`).join('')}
function pricingView(){const d=state.draft;return heading('RATES / ALL VEHICLES','Pricing, fully controlled.','Edit your public prices and default business rates. Each business can also have its own individual pricing.',`<button class="tm-primary" id="tm-save-site">Save pricing changes ↗</button>`)+`<div class="tm-settings-grid">${d.vehicles.map((v,i)=>`<div class="tm-form-card"><h3>${esc(v.name)}</h3><div class="tm-field"><label>Public price (CAD)</label><input type="number" min="0" max="10000" data-sitepath="vehicles.${i}.price" value="${esc(v.price)}"></div><div class="tm-field"><label>Business default (CAD)</label><input type="number" min="0" max="10000" data-sitepath="businessPrices.${v.id}" value="${esc(d.businessPrices[v.id])}"></div></div>`).join('')}</div>`}
function galleryView(){const d=state.draft;return heading('WORK / VISUAL PROOF','Your photo gallery.','Upload the real work you want customers to see. Gallery changes publish only after saving.',`<button class="tm-primary" id="tm-save-site">Save gallery changes ↗</button>`)+`<div class="tm-form-card"><div class="tm-field"><label>Upload image (JPG/PNG/WebP, 750KB maximum)</label><input type="file" id="tm-image-upload" accept="image/jpeg,image/png,image/webp"></div><div class="tm-actions"><button class="tm-outline" id="tm-upload-btn">Upload photo</button><button class="tm-outline" id="tm-image-link-btn">Add by image URL</button></div></div><div class="tm-gallery" style="margin-top:18px">${d.gallery.map((img,i)=>`<div class="tm-gallery-item"><img src="${esc(img.src)}" alt="${esc(img.alt||img.caption)}"><div class="tm-gallery-desc"><strong>${esc(img.caption||'TM Detailers photo')}</strong><button data-remove-image="${i}">Remove photo</button></div></div>`).join('')||'<div class="tm-empty">No photos uploaded. Add real TM Detailers work above.</div>'}</div>`}
function settingsView(){const d=state.draft;return heading('RULES / CONTACT / CAPACITY','Business settings.','Adjust your booking limits, customer location information and opening availability from one place.',`<button class="tm-primary" id="tm-save-site">Save business settings ↗</button>`)+`<div class="tm-settings-grid"><div class="tm-form-card"><h3>Booking operations</h3><div class="tm-field"><label><input type="checkbox" data-sitecheck="booking.enabled" ${d.booking.enabled?'checked':''}> Accept booking requests</label></div><div class="tm-field"><label>Maximum bookings per day</label><input type="number" min="1" max="6" data-sitepath="booking.maxPerDay" value="${esc(d.booking.maxPerDay)}"></div><div class="tm-field"><label>Available times (comma-separated)</label><input id="tm-time-slots" value="${esc(d.booking.timeSlots.join(', '))}"></div><div class="tm-field"><label>Blocked dates (YYYY-MM-DD, comma-separated)</label><textarea id="tm-blocked-dates">${esc(d.booking.blockedDates.join(', '))}</textarea></div></div><div class="tm-form-card"><h3>Customer information</h3><div class="tm-field"><label>Customer contact email</label><input data-sitepath="contact.email" value="${esc(d.contact.email)}"></div><div class="tm-field"><label>Phone</label><input data-sitepath="contact.phone" value="${esc(d.contact.phone)}"></div><div class="tm-field"><label>Drop-off address (only publish if safe to share)</label><input data-sitepath="contact.dropoffAddress" value="${esc(d.contact.dropoffAddress||'')}"></div><div class="tm-field"><label>Mobile detail requirements</label><textarea data-sitepath="contact.locationNote">${esc(d.contact.locationNote)}</textarea></div></div></div><div class="tm-split-note">The seven-day public booking window is enforced by the existing server. Changing capacity or opening times here takes effect only when settings are saved.</div>`}
function assistantView(){return heading('STUDIO ASSISTANT / DRAFTS','Say what you want changed.','A starting point for natural-language edits. The safe draft helper below is local; a real generative AI connection is not configured.',`<button class="tm-outline" data-go="website">Manual website editor ↗</button>`)+`<div class="tm-two-col"><div class="tm-form-card"><h3>Make a request</h3><div class="tm-split-note">Examples: “Change the homepage title to Precision Matters”, “Make Christmas the active theme”, or “Set SUV price to 110”.</div><label for="tm-assistant-prompt">What do you want to change?</label><textarea id="tm-assistant-prompt" rows="5" placeholder="Tell me what to change..." style="margin-top:9px"></textarea><div class="tm-actions"><button class="tm-primary" id="tm-prepare-draft">Prepare a draft ↗</button></div><div id="tm-assistant-result" class="tm-assistant-chat" style="margin-top:20px"></div></div><div class="tm-panel"><div class="tm-panel-head"><h2>What this can do now</h2></div><div class="tm-panel-body"><p class="tm-muted" style="line-height:1.8">Prepare changes to a limited set of website settings. Show exactly what would change, and require approval before saving.</p><div class="tm-divider"></div><p class="tm-muted" style="line-height:1.8"><strong>Not yet connected:</strong> open-ended AI redesign, arbitrary code editing, and automatic deployment. These would need a private AI key, separate code-editing service and preview/rollback safeguards. This panel does not pretend otherwise.</p></div></div></div>`}
function bindView(){const q=$('#tm-book-search');if(q){q.oninput=e=>{state.filters.text=e.target.value;drawBookingRows()};$('#tm-book-status').onchange=e=>{state.filters.status=e.target.value;drawBookingRows()};$('#tm-book-source').onchange=e=>{state.filters.source=e.target.value;drawBookingRows()};drawBookingRows()}const p=$('#tm-calendar-prev');if(p)p.onclick=()=>{state.calendarStart=Math.max(0,state.calendarStart-14);draw()};const n=$('#tm-calendar-next');if(n)n.onclick=()=>{state.calendarStart=Math.min(84,state.calendarStart+14);draw()};const open=$('#tm-show-open');if(open)open.onclick=()=>{open.classList.add('active');$('#tm-show-reviewed').classList.remove('active');$('#tm-requests-list').innerHTML=requestList(state.requests.filter(x=>x.status==='open'))};const closed=$('#tm-show-reviewed');if(closed)closed.onclick=()=>{closed.classList.add('active');$('#tm-show-open').classList.remove('active');$('#tm-requests-list').innerHTML=requestList(state.requests.filter(x=>x.status!=='open'))};const create=$('#tm-new-business');if(create)create.onclick=()=>businessModal();const save=$('#tm-save-site');if(save)save.onclick=saveSite;const reset=$('#tm-reset-draft');if(reset)reset.onclick=()=>{state.draft=clone(state.site);draw();toast('Draft discarded')};const upload=$('#tm-upload-btn');if(upload)upload.onclick=uploadMedia;const addUrl=$('#tm-image-link-btn');if(addUrl)addUrl.onclick=()=>urlModal();const prepare=$('#tm-prepare-draft');if(prepare)prepare.onclick=prepareDraft;}
function openDrawer(html){$('#tm-drawer-body').innerHTML=html;$('#tm-drawer').hidden=false;$('#tm-scrim').hidden=false;document.body.style.overflow='hidden';$('#tm-drawer-close').focus()}
function closeDrawer(){$('#tm-drawer').hidden=true;$('#tm-scrim').hidden=true;document.body.style.overflow=''}
function modal(html){$('#tm-modal-body').innerHTML=html;$('#tm-modal-scrim').hidden=false;document.body.style.overflow='hidden';$('#tm-modal-close').focus()}
function closeModal(){$('#tm-modal-scrim').hidden=true;document.body.style.overflow=''}
function bookingDrawer(id){const b=state.bookings.find(x=>x.id===id);if(!b)return toast('Booking not found',true);state.selected=id;const field=(label,name,value,type='text',extra='')=>`<div class="tm-field"><label>${label}</label><input name="${name}" type="${type}" value="${esc(value||'')}" ${extra}></div>`;openDrawer(`<h2 id="tm-drawer-title">${esc(b.customer_name)}</h2><p class="tm-d-sub">${esc(b.reference)} · ${statusTag(b.status)}${b.business_label?' · '+esc(b.business_label):''}</p><div class="tm-actions" style="margin:12px 0 20px"><a class="tm-primary" href="/track/?ref=${encodeURIComponent(b.reference)}&owner=1" target="_blank" rel="noopener">View &amp; edit the customer tracker ↗</a></div><p class="tm-muted" style="font-size:12px">Opens the exact progress page your customer sees, with owner-only controls for every visible detail and before/after photos.</p><form id="tm-edit-booking"><div class="tm-settings-grid">${field('Customer name','name',b.customer_name)}${field('Phone','phone',b.phone,'tel')}${field('Email address','email',b.email,'email')}<div class="tm-field"><label>Vehicle</label><select name="vehicle">${state.site.vehicles.map(v=>`<option value="${esc(v.id)}" ${b.vehicle===v.id?'selected':''}>${esc(v.name)}</option>`).join('')}</select></div>${field('Date','date',b.appointment_date,'date')}${field('Time','time',b.appointment_time,'time')}<div class="tm-field"><label>Service location</label><select name="location"><option value="dropoff" ${b.service_location==='dropoff'?'selected':''}>Drop-off</option><option value="mobile" ${b.service_location==='mobile'?'selected':''}>Mobile</option></select></div>${field('Price in CAD','price',b.quoted_price,'number','min="0" max="10000"')}<div class="tm-field tm-field-full"><label>Address / location</label><input name="address" value="${esc(b.address||'')}"></div><div class="tm-field tm-field-full"><label>Booking status</label><select name="status">${['pending','confirmed','in_progress','completed','cancelled'].map(s=>`<option value="${s}" ${b.status===s?'selected':''}>${s[0].toUpperCase()+s.slice(1)}</option>`).join('')}</select></div><div class="tm-field tm-field-full"><label>Owner notes</label><textarea name="notes">${esc(b.notes||'')}</textarea></div></div><div class="tm-actions"><button type="submit" class="tm-primary" id="tm-save-booking">Save booking changes ↗</button><button type="button" class="tm-outline" id="tm-cancel-drawer">Cancel</button></div><div class="tm-danger-area"><button type="button" class="tm-danger" id="tm-delete-booking">Delete this booking…</button><p class="tm-muted" style="font-size:11px">Deletion is permanent and requires the reference code.</p></div></form>`);$('#tm-edit-booking').onsubmit=e=>saveBooking(e,b);$('#tm-cancel-drawer').onclick=closeDrawer;$('#tm-delete-booking').onclick=()=>deleteModal(b);}
async function saveBooking(e,b){e.preventDefault();const f=new FormData(e.currentTarget),payload=Object.fromEntries(f.entries());payload.price=Number(payload.price);const btn=$('#tm-save-booking');btn.disabled=true;try{await request('admin/bookings/'+b.id,{method:'PUT',body:JSON.stringify(payload)});await refresh();closeDrawer();draw();toast('Booking updated successfully')}catch(err){toast(err.message,true)}finally{btn.disabled=false}}
function deleteModal(b){modal(`<span class="tm-overline">PERMANENT ACTION</span><h2 id="tm-modal-title">Delete ${esc(b.reference)}?</h2><p>Deleting a booking removes it from the database and stops the customer's reference lookup. Type the exact reference to confirm.</p><div class="tm-field"><label>Booking reference</label><input id="tm-delete-ref" placeholder="${esc(b.reference)}" autocomplete="off"></div><div class="tm-actions"><button id="tm-confirm-delete" class="tm-danger" disabled>Delete permanently</button><button class="tm-outline" id="tm-cancel-delete">Keep booking</button></div>`);$('#tm-delete-ref').oninput=e=>$('#tm-confirm-delete').disabled=e.target.value.trim().toUpperCase()!==b.reference;$('#tm-cancel-delete').onclick=closeModal;$('#tm-confirm-delete').onclick=async()=>{try{await request('admin/bookings/'+b.id,{method:'DELETE',body:JSON.stringify({reference:b.reference})});closeModal();closeDrawer();await refresh();draw();toast('Booking deleted')}catch(err){toast(err.message,true)}};}
async function reviewRequest(id,status){const r=state.requests.find(x=>x.id===id);if(!r)return;try{await request('admin/requests/'+id,{method:'PUT',body:JSON.stringify({status})});await refresh();draw();toast('Request marked '+status+'. Update the booking separately as needed.')}catch(err){toast(err.message,true)}}
function businessModal(){modal(`<span class="tm-overline">COMMERCIAL / ACCOUNT CREATION</span><h2 id="tm-modal-title">New business account</h2><form id="tm-create-company"><div class="tm-field"><label>Company name</label><input name="label" required placeholder="Company name"></div><div class="tm-field"><label>Access code (optional)</label><input name="code" placeholder="TM-BIZ..." autocomplete="off"></div><div class="tm-settings-grid">${state.site.vehicles.map(v=>`<div class="tm-field"><label>${esc(v.name)} CAD</label><input data-newprice="${esc(v.id)}" type="number" min="0" max="10000" value="${esc(state.site.businessPrices[v.id]||v.price)}"></div>`).join('')}</div><button class="tm-primary tm-full">Create company ↗</button></form>`);$('#tm-create-company').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;const prices=Object.fromEntries([...f.querySelectorAll('[data-newprice]')].map(x=>[x.dataset.newprice,Number(x.value)]));try{const data=await request('admin/business',{method:'POST',body:JSON.stringify({label:f.elements.namedItem('label').value,code:f.elements.namedItem('code').value,prices})});await refresh();draw();modal(`<h2 id="tm-modal-title">Company created</h2><p>Share this code privately with the business contact. It will only be shown now.</p><div class="tm-field"><label>Business access code</label><input id="tm-created-code" readonly value="${esc(data.code)}"></div><button class="tm-primary tm-full" id="tm-copy-code">Copy code</button>`);$('#tm-copy-code').onclick=async()=>{await copyText(data.code);toast('Code copied')}}catch(err){toast(err.message,true)}}}
function businessEdit(id){const a=state.accounts.find(x=>x.id===id);if(!a)return;modal(`<span class="tm-overline">COMPANY RATE MANAGEMENT</span><h2 id="tm-modal-title">${esc(a.label)}</h2><form id="tm-update-company"><div class="tm-field"><label>Company name</label><input name="label" value="${esc(a.label)}"></div><div class="tm-field"><label><input type="checkbox" name="active" ${a.active?'checked':''}> Account active</label></div><div class="tm-settings-grid">${state.site.vehicles.map(v=>`<div class="tm-field"><label>${esc(v.name)} CAD</label><input data-company-price="${esc(v.id)}" type="number" min="0" max="10000" value="${esc(a.prices[v.id]??0)}"></div>`).join('')}</div><button class="tm-primary tm-full">Save company rates ↗</button></form>`);$('#tm-update-company').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;const prices=Object.fromEntries([...f.querySelectorAll('[data-company-price]')].map(x=>[x.dataset.companyPrice,Number(x.value)]));try{await request('admin/business/'+id,{method:'PUT',body:JSON.stringify({label:f.elements.namedItem('label').value,active:f.elements.namedItem('active').checked,prices})});closeModal();await refresh();draw();toast('Company updated')}catch(err){toast(err.message,true)}}}
async function showFleet(id){const a=state.accounts.find(x=>x.id===id);try{const r=await request('admin/business/'+id+'/fleet');modal(`<span class="tm-overline">COMPANY FLEET</span><h2 id="tm-modal-title">${esc(a?.label||'Business')} fleet</h2><h3>Departments</h3><div class="tm-rows">${r.departments?.map(d=>`<p>${esc(d.name)}</p>`).join('')||'<p class="tm-muted">No departments registered.</p>'}</div><div class="tm-divider"></div><h3>Registered vehicles</h3><div class="tm-rows">${r.fleet?.map(f=>`<div class="tm-row-card"><strong>${esc(f.make)} ${esc(f.model)} (${esc(f.model_year||'')})</strong><span>${esc(f.label||'')} · ${esc(f.department||'')}</span></div>`).join('')||'<p class="tm-muted">No registered fleet vehicles.</p>'}</div>`)}catch(err){toast(err.message,true)}}
async function rotateCode(id){modal(`<h2 id="tm-modal-title">Rotate access code?</h2><p>The previous code will stop working for this company. Existing bookings remain unchanged.</p><div class="tm-actions"><button class="tm-primary" id="tm-confirm-rotate">Generate new code</button><button class="tm-outline" id="tm-cancel-rotate">Cancel</button></div>`);$('#tm-cancel-rotate').onclick=closeModal;$('#tm-confirm-rotate').onclick=async()=>{try{const r=await request('admin/business/'+id+'/rotate',{method:'POST',body:JSON.stringify({})});modal(`<h2 id="tm-modal-title">New access code</h2><p>Share this code securely. It won't be displayed again.</p><input readonly value="${esc(r.code)}"><button class="tm-primary tm-full" id="tm-copy-rotated" style="margin-top:15px">Copy new code</button>`);$('#tm-copy-rotated').onclick=()=>copyText(r.code)}catch(err){toast(err.message,true)}}}
function setPath(obj,path,value){const steps=path.split('.');let cur=obj;for(const s of steps.slice(0,-1))cur=cur[s];cur[steps.at(-1)]=value;}
function livePreview(){const d=state.draft,p=d.themeProfiles[d.theme]||{};const heading=$('#tm-web-title');if(heading)heading.textContent=p.headline||d.hero.title;const desc=$('#tm-web-description');if(desc)desc.textContent=p.description||d.hero.description;const greet=$('#tm-web-greeting');if(greet)greet.textContent=p.greeting||'TM DETAILERS';const bg=$('#tm-web-preview');if(bg)bg.style.background=p.background||'#1d2320'}
async function saveSite(){const btn=$('#tm-save-site');if(btn)btn.disabled=true;try{const r=await request('admin/site',{method:'PUT',body:JSON.stringify({site:state.draft})});state.site=r.site;state.draft=clone(r.site);toast('Website changes saved');draw()}catch(err){toast(err.message,true)}finally{if(btn)btn.disabled=false}}
async function uploadMedia(){const file=$('#tm-image-upload').files?.[0];if(!file)return toast('Select an image first',true);if(file.size>750000)return toast('Image must be under 750KB',true);try{const f=new FormData();f.append('image',file);const r=await request('admin/media',{method:'POST',body:f});state.draft.gallery.push({id:crypto.randomUUID(),src:r.url,link:'',alt:'TM Detailers detailing work',caption:file.name.replace(/\.[^.]+$/,'')});draw();toast('Image uploaded. Press Save gallery changes to publish.')}catch(err){toast(err.message,true)}}
function urlModal(){modal(`<h2 id="tm-modal-title">Add gallery photo by URL</h2><div class="tm-field"><label>HTTPS image URL</label><input id="tm-url-img" placeholder="https://..."></div><div class="tm-field"><label>Caption</label><input id="tm-url-caption" placeholder="Interior detail"></div><button class="tm-primary tm-full" id="tm-url-add">Add to draft</button>`);$('#tm-url-add').onclick=()=>{const url=$('#tm-url-img').value.trim();if(!/^https:\/\/[^\s<>"']+$/i.test(url))return toast('Enter a valid HTTPS address',true);state.draft.gallery.push({id:crypto.randomUUID(),src:url,link:'',alt:$('#tm-url-caption').value||'TM Detailers photo',caption:$('#tm-url-caption').value||'New photo'});closeModal();draw();toast('Image added to draft. Save to publish.')}}
async function copyText(value){try{await navigator.clipboard.writeText(value);toast('Copied to clipboard')}catch{toast('Select the code and copy it manually',true)}}
function prepareDraft(){const text=$('#tm-assistant-prompt').value.trim();if(!text)return toast('Enter a request first',true);const q=text.toLowerCase();const next=clone(state.draft);let changes=[];const theme=themeCatalog.find(([id,label])=>id!=='default'&&new RegExp('\\b'+id+'\\b','i').test(text));if(theme&&/(activate|enable|switch|change|turn|set|make)/.test(q)){next.theme=theme[0];changes.push('Set website theme to '+theme[1])}const p=/\b(suv|sedan|truck|pickup|van|sprinter)\b.*?\b(?:\$|to |at )\s*(\d{2,4})\b/i.exec(text);if(p){const id=p[1].toLowerCase()==='pickup'?'truck':p[1].toLowerCase();const v=next.vehicles.find(x=>x.id===id);if(v){v.price=Number(p[2]);changes.push('Set public '+v.name+' price to $'+p[2])}}const hero=/\b(?:title|headline)\b\s+(?:to|as)\s+["“]?([^"”\n]+)$/i.exec(text);if(hero){next.hero.title=hero[1].trim();changes.push('Set homepage title to “'+next.hero.title+'”')}if(!changes.length){$('#tm-assistant-result').innerHTML='<div class="tm-message"><small>DRAFT HELPER</small>I could not safely interpret that request. Try a theme switch, a public vehicle price, or a headline change. Open Website editor for anything else.</div>';return}state.assistantDraft=next;$('#tm-assistant-result').innerHTML=`<div class="tm-message"><small>PROPOSED CHANGES · NOT PUBLISHED</small>${changes.map(x=>'<p>✓ '+esc(x)+'</p>').join('')}<div class="tm-actions"><button id="tm-accept-assistant" class="tm-primary">Accept as draft →</button><button id="tm-reject-assistant" class="tm-outline">Discard</button></div></div>`;$('#tm-accept-assistant').onclick=()=>{state.draft=state.assistantDraft;state.assistantDraft=null;navigate('website');toast('Draft prepared. Review and Save to publish.')};$('#tm-reject-assistant').onclick=()=>{state.assistantDraft=null;$('#tm-assistant-result').innerHTML=''}}
function showCommand(){const el=$('#tm-command-scrim');el.hidden=false;$('#tm-command-input').value='';drawCommand('');$('#tm-command-input').focus()}
function hideCommand(){$('#tm-command-scrim').hidden=true}
function drawCommand(q){q=q.toLowerCase().trim();const matches=state.bookings.filter(x=>[x.reference,x.customer_name,x.email,x.phone,x.business_label,x.fleet_make,x.fleet_model].some(a=>String(a||'').toLowerCase().includes(q))).slice(0,8);$('#tm-command-results').innerHTML=matches.map(x=>`<button data-booking-id="${esc(x.id)}">${esc(x.customer_name)} · ${esc(x.reference)} <small class="tm-muted">${dateFmt(x.appointment_date)}</small></button>`).join('')||'<div class="tm-empty">No matching booking.</div>'}
async function boot(){document.getElementById('tm-login-form').addEventListener('submit',signin);$('#tm-signout').onclick=signout;$('#tm-refresh').onclick=async()=>{await refresh();draw();toast('Updated from Cloudflare')};$('#tm-drawer-close').onclick=closeDrawer;$('#tm-scrim').onclick=closeDrawer;$('#tm-modal-close').onclick=closeModal;$('#tm-modal-scrim').onclick=e=>{if(e.target===e.currentTarget)closeModal()};$('#tm-search-open').onclick=showCommand;$('#tm-command-scrim').onclick=e=>{if(e.target===e.currentTarget)hideCommand()};$('#tm-command-input').oninput=e=>drawCommand(e.target.value);$('#tm-menu-btn').onclick=()=>$('#tm-sidebar').classList.toggle('open');$$('.tm-nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$('#tm-main').addEventListener('input',e=>{if(e.target.dataset.sitepath!==undefined){let val=e.target.value;if(e.target.type==='number')val=Number(val);setPath(state.draft,e.target.dataset.sitepath,val);livePreview()}if(e.target.dataset.sitecheck!==undefined){setPath(state.draft,e.target.dataset.sitecheck,e.target.checked)}if(e.target.dataset.themeprop!==undefined){state.draft.themeProfiles[state.draft.theme][e.target.dataset.themeprop]=e.target.value;livePreview()}if(e.target.dataset.seasonPrice!==undefined){const x=e.target.value;const p=state.draft.themeProfiles[state.draft.theme].prices;if(x==='')delete p[e.target.dataset.seasonPrice];else p[e.target.dataset.seasonPrice]=Number(x)}if(e.target.id==='tm-time-slots'){state.draft.booking.timeSlots=e.target.value.split(',').map(x=>x.trim()).filter(Boolean)}if(e.target.id==='tm-blocked-dates'){state.draft.booking.blockedDates=e.target.value.split(',').map(x=>x.trim()).filter(Boolean)}});document.addEventListener('click',async e=>{const target=e.target.closest('button');if(!target)return;if(target.dataset.view)return;const nav=target.closest('[data-go]');if(nav){navigate(nav.dataset.go);return}if(target.dataset.bookingId){hideCommand();bookingDrawer(target.dataset.bookingId);return}if(target.dataset.calendarDay){const d=target.dataset.calendarDay,list=state.bookings.filter(x=>x.appointment_date===d&&x.status!=='cancelled');$('#tm-day-detail').innerHTML=`<div class="tm-panel-head"><h2>${dateFmt(d)}</h2><span>${list.length} booking${list.length===1?'':'s'}</span></div><div class="tm-panel-body">${list.map(b=>`<div class="tm-appointment"><div class="tm-appointment-time">${tFmt(b.appointment_time)}</div><div><strong>${esc(b.customer_name)}</strong><p>${esc(vehicleName(b.vehicle))} · ${esc(b.business_label||'Public')}</p></div><button class="tm-link" data-booking-id="${esc(b.id)}">Edit ↗</button></div>`).join('')||'<div class="tm-empty">No bookings on this date.</div>'}</div>`;return}if(target.dataset.review)await reviewRequest(target.dataset.request,target.dataset.review);if(target.dataset.companyEdit)businessEdit(target.dataset.companyEdit);if(target.dataset.companyFleet)await showFleet(target.dataset.companyFleet);if(target.dataset.companyRotate)await rotateCode(target.dataset.companyRotate);if(target.dataset.removeImage!==undefined){state.draft.gallery.splice(Number(target.dataset.removeImage),1);draw();toast('Removed from draft; save to publish.')}if(target.dataset.theme!==undefined){state.draft.theme=target.dataset.theme;draw();toast('Seasonal edition selected in draft. Save to publish.')}});$('#tm-command-input').addEventListener('keydown',e=>{if(e.key==='Enter'){const first=$('#tm-command-results [data-booking-id]');if(first)first.click()}});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();showCommand()}if(e.key==='Escape'){hideCommand();closeDrawer();closeModal();$('#tm-sidebar').classList.remove('open')}});if(DEMO){$('#tm-pass').value='demo';const gate=$('#tm-gate');gate.querySelector('.tm-gate-content p').textContent='This is a local interactive demo with fictional data. Enter any password to explore.'}else{try{await request('logout',{method:'POST',body:JSON.stringify({})})}catch{}}}
boot();
